const e={ocnal:{baipishu:"Белая книга",home1:"Откройте мир цифровых валют",home2:"Пополнить сейчас",home3:"Имя",home4:"Цена",home5:"Изменение за 24 часа",home6:"Торговля",home7:"Начать",home8:"Создать аккаунт",home9:"Зарегистрируйтесь, чтобы получить больше преимуществ и услуг",home10:"Регистрация",home11:"Пополнить счёт",home12:"Пополните свой счёт и начните инвестировать в криптовалюты",home13:"Пополнить крипто",home14:"Начать торговлю",home15:"Продавайте, покупайте или копируйте сделки — откройте больше возможностей",home16:"Изучить рынок",home17:"Рынок криптовалют стремительно развивается, включая цифровые валюты, блокчейн и многое другое. Перспективы велики, но инвестиции требуют осторожности.",home18:"Спот",home19:"Реальная торговля на спотовом рынке с быстрыми изменениями цен.",home20:"Бессрочный контракт",home21:"Контрактная торговля предоставляет кредитное плечо и позволяет получать высокую прибыль.",home22:"Опционы",home23:"Опционная торговля предлагает гибкие стратегии хеджирования для контроля рисков и получения дохода.",home24:"AI-инвестиции",home25:"Планируйте с уверенностью. Инвестируйте разумно. Меньше беспокойтесь.",home26:"Самая высокая годовая доходность в истории",home27:"Текущий",home28:"Фиксированный",home29:"Купить сейчас",home30:"Каждый может использовать цифровую валюту",home31:"От первого опыта торговли криптовалютой до первой покупки финансового продукта — платформа поможет вам легко зарабатывать монеты.",home32:"Узнайте о криптовалюте",home33:"Изучите всё о криптовалютах и начните инвестировать",home34:"Часто задаваемые вопросы",home35:"Готовы начать своё крипто-путешествие?",home36:"Что такое криптовалютная биржа?",home37:"Криптовалютные биржи — это цифровые площадки, где пользователи могут покупать и продавать криптовалюты, такие как Bitcoin, Ethereum и Tether. Binance — крупнейшая биржа по объёму торгов.",home38:"Какие продукты предлагает платформа?",home39:"Как ведущая мировая криптобиржа, она обслуживает более 150 миллионов пользователей из 180 стран. С низкими комиссиями она предлагает свыше 350 торгуемых криптовалют.<br><br>На платформе пользователи могут:<br><br>1. Торговать сотнями валют и торговых пар.<br><br>2. Покупать и продавать криптовалюты через спотовую торговлю.<br><br>3. Зарабатывать проценты через управление активами.",home40:"Как торговать криптовалютами на платформе",home41:"На платформе вы можете торговать сотнями криптовалют на спотовом, фьючерсном и опционном рынках. Зарегистрируйтесь, подтвердите личность и внесите депозит, чтобы начать.",home42:"Безопасна ли эта платформа?",home43:"Платформа обеспечивает безопасную и надёжную торговлю. Мы используем передовые технологии безопасности и профессиональную команду. Все активы пользователей полностью подтверждены в соотношении 1:1.",home44:"Как восстановить забытый пароль?",home45:"Нажмите «Забыли пароль?» на странице входа и сбросьте его.",home46:"Зачем нужна идентификация личности?",home47:"Чтобы защитить ваши средства и предотвратить отмывание денег, мы должны убедиться, что ваш счёт связан с вашими личными данными.",home48:"Рынки",home49:"Глобальный рынок торговли криптовалютами поддерживает многовалютные операции, обеспечивая безопасность и эффективность.",home50:"Мой аккаунт",home51:"Пополнить",home52:"Вывести",home53:"Конвертировать",home54:"Популярное",home55:"Инвестируйте в недавно выпущенные токены и получите высокий потенциал доходности",home56:"Новости",home57:"Почему выбирают нас?",home58:"Нам доверяют миллионы пользователей",home59:"Количество пользователей",home60:"Партнёрская организация",home61:"Минимальные комиссии за транзакции",home62:"Партнёры",home63:"Объём за 24 часа",jianguanzhengshu:"Регуляторный сертификат",falvzhengmingshu:"Юридический сертификат"}};export{e as default};
